&lt;ul&gt;
     &lt;li&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Warm clothing and blankets&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Water and nonâ'perishable food&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Flashlight and extra batteries&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
