     &lt;li&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Phone charger and backup power&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

